"use client";
import React, { useEffect } from "react";
import {SearchBar} from "./search-bar.js";
import "../LoginButton.css";
import {profileStore} from "../profile-store.jsx";
import { onSignOut } from "../profileHandlers.jsx";
import {renderAuth} from "../user-auth.jsx";
import { profile } from "node:console";

export const LoginButton = () => {
    const [mode, setMode] = React.useState("create");
    const [showAuth, setShowAuth] = React.useState(false);

    connectedCallback = () => {
        super.connectedCallback();

        window.addEventListener("profile-changed", () => {
            this.showAuth = false;
            this.requestUpdate();
        });
    }

    profileStore.load();

    if (profileStore.loading) {
        return html`<p>Loading...</p>`;
    }

    if (profileStore.user) {
        return html`<p>Welcome, ${profileStore.user.name}</p>
        <button @click=${onSignOut}>Sign out</button>`;
    }

        return (
            <>
                <button onClick={() => setShowAuth(true)} className={mode === "login" ? "login" : 'create'}>
                    {mode === "login" ? "Login" : 'Get Started'}
                </button>

                {showAuth ? (
                    <div className="modal" onClick={() => setShowAuth(false)}>
                        <div class="card" onClick={e => e.stopPropagation()}>
                            {renderAuth(mode, () => setShowAuth(false))}
                        </div>
                    </div>
                ) : null};
            </>
        );
}

customElements.define("login-button", LoginButton);